fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    // Create a new vector with a length of one greater than the original
    let mut result = Vec::with_capacity(arr.len() + 1);
    
    // Iterate over the original array and insert elements into the new array
    for i in 0..=arr.len() {
        if i == idx {
            // Insert the new value at the specified index
            result.push(value);
        } else {
            // Push the original elements, adjusting the index accordingly
            let original_index = if i < idx { i } else { i - 1 };
            result.push(arr[original_index].clone());
        }
    }
    
    result
}